; >S:CHECK-MAN; PUT "CHECK-MAN";; CHECK MANS POS.;;CHECK;; CALLED WITH X,Y SET UP;JSR XY ;* CONVERT TO SCREEN;LDX #3;RUB1;LDY YVAL2,XLDA (SL),YSTA BEHIND,X ;* SAVE TO BUFFER;CMP #197BCC CKOK;CMP #244BCS CKOK;LDA #1STA HIT;CKOK;DEXBPL RUB1;RTS;;----------------------------;MANDED;; CALLED WHEN THE EXPLOSION; IS ON THE SCREEN TO SEE IF; THE MAN DIED.;; *NB MANL,MANL+1 HAVE BEEN;     SET UP WITH THE TL ADDRESS;     OF THE MAN BEFORE THE;     EXPLOSION STARTED.;LDX #3;MNDE2;LDY YVAL2,XLDA (MANL),Y;CMP #248      ;* EXPLOSION CHARBNE BUTDS     ;* NOT DIED !;LDA #1STA DEADSTA DEDBMB ;* DIED BY BOMB;BUTDS;DEXBPL MNDE2;RTS;;--------------------;FINDTL;LDA #22STA TEMP;FINDE1;LDX #0LDY TEMPJSR XY;LDY #30;FINDE2;LDA (SL),YCMP #28BNE NXTFND;STY TYLDA SLCLCADC TYSTA MANL;LDA SL+1ADC #0STA MANL+1;RTS;NXTFND;DEYBNE FINDE2;DEC TEMPBNE FINDE1;FINDNO;INC $FF19;JMP FINDNO;.END